import React from 'react';

export const NestShadowLogo = ({ className = "", showIcon = true }) => {
  return (
    <div className={`flex items-center gap-3 select-none ${className}`}>
      {showIcon && <span>[Logo]</span>}
      <span className="font-bold text-xl">Nest</span>
    </div>
  );
};
